// Generated bytes are checked in, so ordinary builds need no toolchain.
// This runs the bitmap kernel's tests (`zig build test`), then `zig build`
// (build.zig) with the pinned Zig, which compiles each sub-path's Zig and,
// with its clang, the vendored C, unchanged, to wasm32-freestanding; each
// module is written as base64 into src/<sub-path>/binary.ts, and the
// vendored C's notices into LICENSE.third-party. --check verifies each
// binary's inputs' digest and the notices without building.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { findZig, ZIG_VERSION } from "../../tools/zig.ts";

const here = fileURLToPath(new URL(".", import.meta.url));
const vendor = fileURLToPath(new URL("../../vendor/", import.meta.url));

/** A directory's files that match, sorted: more than build.zig compiles, never less. */
const files = (dir: string, pattern: RegExp) =>
  readdirSync(dir)
    .filter((name) => pattern.test(name))
    .sort()
    .map((name) => join(dir, name));

interface Binary {
  /** The sub-path, and the folder under src/ with its Zig, wrapper and binary.ts. */
  path: string;
  /** zig-out/bin/<file>.wasm for each export of binary.ts. */
  modules: Record<string, string>;
  /**
   * What each module may import: render's C reports failure through one, and its lines take
   * the host's sine and cosine.
   */
  imports: WebAssembly.ModuleImportDescriptor[];
  /** The vendored files compiled in, beside the package's own. */
  vendored: string[];
  /** The generated file's note on the C's licence. */
  note: string;
}

const BINARIES: Binary[] = [
  {
    path: "mp3",
    modules: { binary: "mp3" },
    imports: [],
    vendored: [join(vendor, "minimp3/minimp3.h"), join(vendor, "minimp3/LICENSE")],
    note: "; minimp3 is CC0-1.0",
  },
  {
    path: "compress",
    modules: { binary: "compress" },
    imports: [],
    vendored: [
      ...files(join(vendor, "zlib"), /\.[ch]$/),
      join(vendor, "zlib/LICENSE"),
      ...files(join(vendor, "lzma-sdk/C"), /\.[ch]$/),
    ],
    note: "; zlib is under the zlib license, the LZMA SDK in the public domain",
  },
  {
    path: "render",
    modules: { binary: "render" },
    imports: [
      { module: "env", name: "cosine", kind: "function" },
      { module: "env", name: "sine", kind: "function" },
      { module: "env", name: "failure", kind: "function" },
    ],
    vendored: [
      ...files(join(vendor, "libtess2/Include"), /\.[ch]$/),
      ...files(join(vendor, "libtess2/Source"), /\.[ch]$/),
      join(vendor, "libtess2/LICENSE.txt"),
    ],
    note: "; libtess2 is under SGI Free Software License B",
  },
];

/** Our notice for the LZMA SDK, which has no licence file to copy. */
const LZMA_SDK = `The LZMA encoder and decoder in this package's WebAssembly binary are
compiled from the LZMA SDK 26.05's C sources (C/LzmaEnc.c, C/LzFind.c,
C/LzmaDec.c and the headers they include), by Igor Pavlov, unchanged but
for line endings in swf2es/lzma-sdk. Each
of those files states:

  Igor Pavlov : Public domain

and the SDK's DOC/lzma-sdk.txt says:

  LZMA SDK is written and placed in the public domain by Igor Pavlov.

  Anyone is free to copy, modify, publish, use, compile, sell, or distribute
  the original LZMA SDK code, either in source code form or as a compiled
  binary, for any purpose, commercial or non-commercial, and by any means.

This notice records where they come from.

https://www.7-zip.org/sdk.html
`;

/** pixels.zig's perlinNoise noise, derived from SVG 1.1's feTurbulence reference implementation. */
const FE_TURBULENCE = `src/render/pixels.zig's noise for BitmapData.perlinNoise is derived from
the reference implementation of feTurbulence in Scalable Vector Graphics
(SVG) 1.1 (Second Edition),
https://www.w3.org/TR/SVG11/filters.html#feTurbulenceElement

Copyright © 2015 W3C® (MIT, ERCIM, Keio, Beihang). This software or
document includes material copied from or derived from SVG 1.1, under the
W3C Software and Document License:
https://www.w3.org/Consortium/Legal/2015/copyright-software-and-document
`;

/** Each vendored library's notice, verbatim, and the derived work's, under the sub-path that compiles it in. */
function notices(): string {
  const sections: [string, string][] = [
    ["@swf2es/native/compress: zlib", readFileSync(join(vendor, "zlib/LICENSE"), "utf8")],
    ["@swf2es/native/compress: the LZMA SDK", LZMA_SDK],
    ["@swf2es/native/mp3: minimp3", readFileSync(join(vendor, "minimp3/LICENSE"), "utf8")],
    ["@swf2es/native/render: libtess2", readFileSync(join(vendor, "libtess2/LICENSE.txt"), "utf8")],
    ["@swf2es/native/render: SVG's feTurbulence (perlinNoise)", FE_TURBULENCE],
  ];

  return [
    "Third-party code compiled into @swf2es/native's WebAssembly binaries, each\nnotice verbatim. The package's own code is under the Apache License 2.0.\n",
    ...sections.map(([title, text]) => `${title}\n${"=".repeat(title.length)}\n\n${text}`),
  ].join("\n\n");
}

const shared = [
  fileURLToPath(import.meta.url),
  join(here, "build.zig"),
  ...files(join(here, "include"), /\.h$/),
];

function inputDigest(binary: Binary): string {
  const digest = createHash("sha256").update(ZIG_VERSION);
  const own = files(join(here, "src", binary.path), /\.zig$/);
  for (const file of [...shared, ...own, ...binary.vendored]) {
    digest.update(readFileSync(file));
  }

  return digest.digest("hex");
}

const target = (binary: Binary) => join(here, "src", binary.path, "binary.ts");
const license = join(here, "LICENSE.third-party");
if (process.argv.includes("--check")) {
  for (const binary of BINARIES) {
    if (!readFileSync(target(binary), "utf8").includes(`inputs: ${inputDigest(binary)}`)) {
      throw new Error(`${binary.path} inputs changed; run pnpm --filter @swf2es/native build:wasm`);
    }
  }

  if (readFileSync(license, "utf8") !== notices()) {
    throw new Error("vendored notices changed; run pnpm --filter @swf2es/native build:wasm");
  }
} else {
  // Fresh caches and prefix each time, so nothing of an earlier build is reused.
  const work = mkdtempSync(join(tmpdir(), "swf2es-native-"));
  const zig = (args: string[]) =>
    execFileSync(findZig(), args, {
      cwd: here,
      stdio: "inherit",
      env: {
        ...process.env,
        ZIG_LOCAL_CACHE_DIR: join(work, "cache"),
        ZIG_GLOBAL_CACHE_DIR: join(work, "global"),
      },
    });
  try {
    // The bitmap kernel's own tests, on the host, before the binaries they vouch for.
    zig(["build", "test"]);
    zig(["build", "--prefix", work]);
    for (const binary of BINARIES) {
      const exports: string[] = [];
      for (const [name, file] of Object.entries(binary.modules)) {
        const bytes = readFileSync(join(work, `bin/${file}.wasm`));
        const imports = WebAssembly.Module.imports(await WebAssembly.compile(bytes));
        if (JSON.stringify(imports) !== JSON.stringify(binary.imports)) {
          throw new Error(`unexpected ${file} imports: ${JSON.stringify(imports)}`);
        }

        exports.push(`export const ${name} =\n  "${bytes.toString("base64")}";\n`);
        console.log(`${binary.path} ${file}: ${bytes.length} bytes`);
      }

      writeFileSync(
        target(binary),
        `// Generated by packages/native/build.ts${binary.note}.\n// inputs: ${inputDigest(binary)}\n${exports.join("\n")}`,
      );
    }

    writeFileSync(license, notices());
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}
